package com.nexttv;

import android.app.*;
import android.content.*;
import android.graphics.Rect;
import android.os.*;
import android.view.*;
import android.view.accessibility.AccessibilityNodeInfo;
import org.json.JSONObject;

/** Real mouse wheel → physical arrow-key handoff, without assigning focus to hide a lost-focus bug. */
public class GlobalPointerKeyboardInstrumentation extends com.nexttv.support.NextTvInstrumentation {
 private Activity activity;private android.content.SharedPreferences prefs;private java.util.Map<String,?> saved;private int passed;
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 private JSONObject grid()throws Exception{java.io.StringWriter writer=new java.io.StringWriter();runOnMainSync(()->activity.dump("",null,new java.io.PrintWriter(writer),null));java.util.regex.Matcher m=java.util.regex.Pattern.compile("NextTVGrid (\\{[^\\n]+\\})").matcher(writer.toString());return m.find()?new JSONObject(m.group(1)):new JSONObject();}
 private AccessibilityNodeInfo focused(){return focused(root());}
 private void await(String label,int timeout, java.util.concurrent.Callable<Boolean> condition)throws Exception{long until=SystemClock.uptimeMillis()+timeout;while(SystemClock.uptimeMillis()<until){if(condition.call())return;SystemClock.sleep(80);}throw new IllegalStateException(label+" focus="+focus()+" UI="+tree());}
 private AccessibilityNodeInfo root(){AccessibilityNodeInfo n=getUiAutomation().getRootInActiveWindow();if(n!=null)n.refresh();return n;}

 private void wheel(float amount,long settle){wheelAt(500,350,amount,settle);}
 private void wheelAt(float x,float y,float amount,long settle){MotionEvent.PointerProperties p=new MotionEvent.PointerProperties();p.id=0;p.toolType=MotionEvent.TOOL_TYPE_MOUSE;MotionEvent.PointerCoords c=new MotionEvent.PointerCoords();c.x=x;c.y=y;c.setAxisValue(MotionEvent.AXIS_VSCROLL,amount);long t=SystemClock.uptimeMillis();MotionEvent e=MotionEvent.obtain(t,t,MotionEvent.ACTION_SCROLL,1,new MotionEvent.PointerProperties[]{p},new MotionEvent.PointerCoords[]{c},0,0,1,1,0,0,InputDevice.SOURCE_MOUSE,0);getUiAutomation().injectInputEvent(e,true);e.recycle();if(settle>0)SystemClock.sleep(settle);}
 protected void launch()throws Exception{activity=startActivitySync(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setClassName("com.nexttv","com.nexttv.core.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await("initial Channels menu",()->focus().equals("频道"));SystemClock.sleep(800);}
 private void visible()throws Exception{await("focused card fully visible",()->{JSONObject g=grid();return g.getInt("itemTop")>=g.getInt("viewportStart")&&g.getInt("itemBottom")<=g.getInt("viewportEnd");});}
 protected void pass(String text){passed++;Bundle b=new Bundle();b.putString("stream","PASS "+text+"\n");sendStatus(0,b);}
 private void backToMenu()throws Exception{key(KeyEvent.KEYCODE_ESCAPE);await("Back to Channels menu",()->focus().equals("频道")&&grid().getInt("first")==0);}
 private void restore(){if(activity!=null)runOnMainSync(()->activity.finish());if(saved==null)return;android.content.SharedPreferences.Editor e=prefs.edit().clear();for(java.util.Map.Entry<String,?> i:saved.entrySet()){Object v=i.getValue();String k=i.getKey();if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Float)e.putFloat(k,(Float)v);else if(v instanceof java.util.Set)e.putStringSet(k,(java.util.Set<String>)v);}e.commit();}
 private JSONObject browser()throws Exception{java.io.StringWriter s=new java.io.StringWriter();runOnMainSync(()->activity.dump("",null,new java.io.PrintWriter(s),null));java.util.regex.Matcher m=java.util.regex.Pattern.compile("NextTVBrowser (\\{[^\\n]+\\})").matcher(s.toString());return m.find()?new JSONObject(m.group(1)):new JSONObject();}
 private AccessibilityNodeInfo find(String value,AccessibilityNodeInfo n){if(n==null||!n.refresh())return null;if(value.contentEquals(n.getText()==null?"":n.getText()))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo f=find(value,n.getChild(i));if(f!=null)return f;}return null;}
 protected void click(String label)throws Exception{await(label,()->find(label,root())!=null);AccessibilityNodeInfo n=find(label,root());while(!n.isClickable())n=n.getParent();if(!n.performAction(AccessibilityNodeInfo.ACTION_CLICK))throw new IllegalStateException("Click "+label);waitForIdleSync();SystemClock.sleep(200);}
 private void fullyVisible()throws Exception{await("visible current focus",()->{AccessibilityNodeInfo n=focused();if(n==null)return false;Rect b=new Rect();n.getBoundsInScreen(b);Rect win=new Rect();root().getBoundsInScreen(win);return b.top>=64&&b.bottom<=win.bottom-10&&b.height()>25;});}
 @Override public void onStart(){int result=Activity.RESULT_OK;String report="";try{
  prefs=getTargetContext().getSharedPreferences("nexttv",0);saved=prefs.getAll();prefs.edit().putBoolean("start_live",false).putBoolean("previews",false).putBoolean("auto_update",false).putBoolean("auto_update_epg",false).putBoolean("grid_mode",true).commit();launch();
  key(KeyEvent.KEYCODE_DPAD_RIGHT);key(KeyEvent.KEYCODE_DPAD_RIGHT);await("Settings nav",()->focus().equals("设置"));wheelAt(850,350,-12,700);key(KeyEvent.KEYCODE_DPAD_DOWN);await("Settings enters visible row rather than offscreen first row",()->!focus().equals("设置")&&!focus().contains("节目单地址")&&!focus().isEmpty());fullyVisible();pass("Settings menu after wheel enters current visible row without jumping to EPG address");
  wheelAt(850,350,-10,700);key(KeyEvent.KEYCODE_DPAD_DOWN);fullyVisible();if(focus().contains("节目单地址"))throw new IllegalStateException("Settings handoff jumped to top");pass("Settings row → wheel → keyboard keeps current viewport");key(KeyEvent.KEYCODE_ESCAPE);await("Settings Back to menu",()->focus().equals("设置"));key(KeyEvent.KEYCODE_DPAD_DOWN);await("Settings Back resets entry",()->focus().contains("节目单地址"));pass("Settings explicit Back still resets next entry to first row");
  key(KeyEvent.KEYCODE_ESCAPE);key(KeyEvent.KEYCODE_DPAD_LEFT);key(KeyEvent.KEYCODE_DPAD_LEFT);click("频道分类：全部频道");await("category choice dialog",()->tree(root()).contains("频道分类")&&java.util.Arrays.asList(focus().split("\n")).contains("全部频道"));wheelAt(550,350,-12,700);key(KeyEvent.KEYCODE_DPAD_DOWN);fullyVisible();if(java.util.Arrays.asList(focus().split("\n")).contains("全部频道")||focus().isEmpty())throw new IllegalStateException("Choice handoff lost visible focus");key(KeyEvent.KEYCODE_ESCAPE);pass("shared selection dialog wheel → keyboard focuses visible options without changing selected category");
  click("CCTV1综合");await("real first frame",45000,()->{java.io.StringWriter d=new java.io.StringWriter();runOnMainSync(()->activity.dump("",null,new java.io.PrintWriter(d),null));return d.toString().matches("(?s).*firstFrameMs=[1-9][0-9]*.*");});key(KeyEvent.KEYCODE_ENTER);await("channel browser",()->browser().optString("region").equals("channels"));wheelAt(190,350,-12,700);int first=browser().getInt("channelFirst");if(first==0)throw new IllegalStateException("Channel wheel did not scroll");key(KeyEvent.KEYCODE_DPAD_DOWN);fullyVisible();if(browser().getInt("channelFirst")<first-1)throw new IllegalStateException("Channel handoff jumped to old channel");pass("channel list wheel → keyboard resumes visible channel rather than prior offscreen channel");
  wheelAt(190,350,-9,700);key(KeyEvent.KEYCODE_DPAD_RIGHT);await("Right after wheel opens associated EPG",()->browser().optString("pane").equals("epg"));if(tree(root()).contains("暂无节目单")){key(KeyEvent.KEYCODE_ESCAPE);key(KeyEvent.KEYCODE_ENTER);key(KeyEvent.KEYCODE_DPAD_RIGHT);await("EPG for real fixture channel",()->browser().optString("pane").equals("epg"));}pass("first Right after mouse scroll restores channel focus and expands associated EPG");
  int epgBefore=browser().getInt("epgFirst");wheelAt(540,350,-12,700);int epgScrolled=browser().getInt("epgFirst");key(KeyEvent.KEYCODE_DPAD_DOWN);fullyVisible();if(!focus().matches("(?s).*\\d{2}:\\d{2}.*")||browser().getInt("epgFirst")<epgScrolled-1)throw new IllegalStateException("EPG handoff focus="+focus()+" before="+epgBefore+" scrolled="+epgScrolled+" actual="+browser());pass("programme list wheel → keyboard resumes visible programme in its own column");
  key(KeyEvent.KEYCODE_DPAD_LEFT);await("EPG Left closes EPG",()->browser().optString("pane").equals("channels"));key(KeyEvent.KEYCODE_DPAD_LEFT);await("Groups open",()->browser().optString("region").equals("groups"));wheelAt(90,350,-10,700);key(KeyEvent.KEYCODE_DPAD_DOWN);fullyVisible();Rect b=new Rect();focused().getBoundsInScreen(b);if(b.left>160||b.width()>170)throw new IllegalStateException("Group handoff escaped column "+b);key(KeyEvent.KEYCODE_DPAD_RIGHT);await("Groups Right closes groups",()->browser().optString("pane").equals("channels"));pass("group list shares wheel handoff and symmetric return to channels");key(KeyEvent.KEYCODE_ESCAPE);report="Global pointer/keyboard: "+passed+" groups passed\n";
 }catch(Throwable t){result=Activity.RESULT_CANCELED;report=android.util.Log.getStackTraceString(t);}finally{restore();}Bundle b=new Bundle();b.putString("stream",report);finish(result,b);}
}
